import { contrast, ensureContrast, hexToRgb, oklabToOklch, oklabToRgb, oklchToOklab, rgbToHex, rgbToOklab } from './colors.js'
import type { Skin } from './schema.js'
export const TOKEN_ROLES = ['--dsw-alias-bg-base','--dsw-alias-bg-layer-1','--dsw-alias-label-primary','--dsw-alias-label-secondary','--dsw-alias-label-primary-foreground','--dsw-alias-brand-primary','--dsw-alias-border-l2'] as const
export function deriveTokens(seed: string): Skin['tokens'] { const lch=oklabToOklch(rgbToOklab(hexToRgb(seed))); const tint=(l:number,c:number=lch.c)=>rgbToHex(oklabToRgb(oklchToOklab({l,c,h:lch.h}))); const lightBg=tint(.97,.02), darkBg=tint(.16,.025), lightText=ensureContrast(tint(.18,.03),lightBg), darkText=ensureContrast(tint(.9,.03),darkBg), accent=tint(Math.max(.45,Math.min(.68,lch.l)),Math.max(.08,lch.c)); return {'--dsw-alias-bg-base':{light:lightBg,dark:darkBg},'--dsw-alias-bg-layer-1':{light:tint(.93,.03),dark:tint(.22,.03)},'--dsw-alias-label-primary':{light:lightText,dark:darkText},'--dsw-alias-label-secondary':{light:ensureContrast(tint(.37,.02),lightBg,4.5),dark:ensureContrast(tint(.72,.02),darkBg,4.5)},'--dsw-alias-label-primary-foreground':{light:ensureContrast('#ffffff',accent,4.5),dark:ensureContrast('#ffffff',accent,4.5)},'--dsw-alias-brand-primary':{light:accent,dark:accent},'--dsw-alias-border-l2':{light:tint(.8,.025),dark:tint(.34,.03)}} }
export function preserveLocked(tokens: Skin['tokens'], derived: Skin['tokens'], locks: readonly string[]): Skin['tokens'] { const next={...derived}; for(const key of locks)if(tokens[key])next[key]=tokens[key]; return next }
export function audit(tokens: Skin['tokens']) { const pairs=[['--dsw-alias-label-primary','--dsw-alias-bg-base'],['--dsw-alias-label-secondary','--dsw-alias-bg-base'],['--dsw-alias-label-primary-foreground','--dsw-alias-brand-primary']] as const; return pairs.map(([foreground,background])=>({foreground,background,light:tokens[foreground]&&tokens[background]?Math.round(contrast(tokens[foreground].light,tokens[background].light)*100)/100:0,dark:tokens[foreground]&&tokens[background]?Math.round(contrast(tokens[foreground].dark,tokens[background].dark)*100)/100:0})) }
